    {
         // 此为帮助文档原文本，含有 HTML、CSS 内容，供程序在运行时生成帮助文件。
        public static string style_css = "body {\r\n\tbackground: #FFFFFF;\r\n\tcolor: #000000;\r\n\tfont-family: Tahoma,Arial,\"Microsoft YaHei\",\"宋体\",sans-serif;\r\n\tfont-size: 9pt;\r\n\tline-height: 1.7;\r\n\tmargin: 0;\r\n\tpadding: 0;\r\n}\r\n\r\na {\r\n\tcolor: #0033CC;\r\n\ttext-decoration: none;\r\n}\r\n\r\na:visited {\r\n\tcolor: #551A8B;\r\n}\r\n\r\na:hover {\r\n\tcolor: #CC3300;\r\n\ttext-decoration: underline;\r\n}\r\n\r\nh2 {\r\n\tfont-size: 12pt;\r\n\tcolor: #1F4E79;\r\n\tmargin: 18px 0 6px 0;\r\n\tpadding-bottom: 3px;\r\n\tborder-bottom: 1px solid #C9D8EA;\r\n}\r\n\r\nh3 {\r\n\tfont-size: 10.5pt;\r\n\tcolor: #2F5B8F;\r\n\tmargin: 14px 0 4px 0;\r\n}\r\n\r\np {\r\n\tmargin: 6px 0;\r\n}\r\n\r\nul,ol {\r\n\tmargin: 6px 0 6px 28px;\r\n\tpadding: 0;\r\n}\r\n\r\nli {\r\n\tmargin: 3px 0;\r\n}\r\n\r\ntd,th {\r\n\tfont-size: 9pt;\r\n}\r\n\r\ntable.tbl {\r\n\tborder-collapse: collapse;\r\n}\r\n\r\ntable.tbl th, table.tbl td {\r\n\tborder: 1px solid #7F9DB9;\r\n\tpadding: 4px 8px;\r\n}\r\n\r\ntable.tbl th {\r\n\tbackground-color: #D8E4F0;\r\n\tcolor: #1F4E79;\r\n}\r\n\r\n.note {\r\n\tborder: 1px solid #FFCC66;\r\n\tbackground-color: #FFFFE1;\r\n\tpadding: 8px 10px;\r\n\tmargin: 10px 0;\r\n}\r\n\r\n.tip {\r\n\tborder: 1px solid #99CCFF;\r\n\tbackground-color: #EAF4FF;\r\n\tpadding: 8px 10px;\r\n\tmargin: 10px 0;\r\n}\r\n\r\n.content {\r\n\tmargin: 12px 20px 20px 20px;\r\n}\r\n\r\n.navbar {\r\n\tborder-top: 1px solid #CCCCCC;\r\n\tmargin: 20px 20px 10px 20px;\r\n\tpadding-top: 8px;\r\n}\r\n\r\n.footer {\r\n\tborder-top: 1px solid #CCCCCC;\r\n\tbackground-color: #F4F6F9;\r\n\tpadding: 8px 16px;\r\n\tfont-size: 8.5pt;\r\n\tcolor: #666666;\r\n\ttext-align: center;\r\n}\r\n\r\n.crumb {\r\n\tbackground-color: #EAF1F9;\r\n\tborder-bottom: 1px solid #B9CDE4;\r\n\tpadding: 4px 16px;\r\n\tfont-size: 9pt;\r\n}\r\n\r\n.banner {\r\n\tbackground-color: #1F4E79;\r\n}\r\n\r\n.banner h1 {\r\n\tmargin: 0;\r\n\tfont-size: 14pt;\r\n\tfont-weight: bold;\r\n\tcolor: #FFFFFF;\r\n}\r\n\r\n.code {\r\n\tfont-family: \"Courier New\",Courier,monospace;\r\n\tfont-size: 9pt;\r\n}\r\n  .bold-red {\r\n    color: red;\r\n    font-weight: bold;\r\n}";
        public static string index_htm = "<!DOCTYPE HTML PUBLIC \"-//W3C//DTD HTML 4.01 Transitional//EN\" \"http://www.w3.org/TR/html4/loose.dtd\">\r\n<html lang=\"zh-CN\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\">\r\n<title>欢迎 - FPACTool 帮助</title>\r\n<link rel=\"stylesheet\" href=\"style/style.css\">\r\n</head>\r\n<body>\r\n\r\n<!-- 顶部标题栏 -->\r\n<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" class=\"banner\">\r\n<tr>\r\n<td style=\"padding:10px 16px;\"><h1>欢迎</h1></td>\r\n<td style=\"padding:10px 16px; text-align:right;\"><a href=\"index.htm\" style=\"color:#FFFFFF;\">FPACTool 帮助主页</a></td>\r\n</tr>\r\n</table>\r\n\r\n<!-- 当前位置 -->\r\n<div class=\"crumb\"><b>位置：</b><a href=\"index.htm\">FPACTool 帮助</a></div>\r\n\r\n<!-- 正文内容区 -->\r\n<div class=\"content\">\r\n\r\n<h2>欢迎使用 FPACTool</h2>\r\n<p>FPACTool 是一款用于 <b>PAC 文件</b>打包与解包的小工具，界面简洁、操作直观，既能够生成用于游戏 MOD 补丁的 PAC 包，也能够从 PAC 包中提取所需内容。同时支持 DDS 格式图像的预览，从而省去要先提取再用专门工具打开的麻烦。</p>\r\n\r\n<p>截至当前版本，本工具已适配以下游戏的 PAC 文件打包、提取：</p>\r\n<ul>\r\n<li>空之轨迹 1st（The Legend of Heroes: Trails in the Sky 1st）</li>\r\n<li>空之轨迹 2nd（The Legend of Heroes: Trails in the Sky 2nd）</li>\r\n<li>亰都幻都 樱花幻舞（KYOTO XANADU -the Blooming Phantom-）</li>\r\n</ul>\r\n<p>未来同厂商的游戏的 PAC 文件理论上适配，请自行尝试。</p>\r\n<h2>快速上手</h2>\r\n<ul>\r\n<li>若要将本地文件与文件夹制作成 PAC 文件，请参阅 <a href=\"Pack.htm\">打包 PAC</a>。</li>\r\n<li>若要打开 PAC 文件并提取其中的内容，请参阅 <a href=\"Unpack.htm\">浏览/提取 PAC</a>。</li>\r\n<li>有关 DDS 浏览的内容，请参阅 <a href=\"DDSView.htm\">DDS 浏览</a>。</li>\r\n<li>若在使用过程中遇到问题，请先查看 <a href=\"FAQ.htm\">疑难解答</a>。</li>\r\n</ul>\r\n\r\n<h2>本帮助的组织方式</h2>\r\n<p>本帮助文件按主题组织，您可以通过左侧的目录树浏览全部主题，也可以使用页面底部的“上一页 / 下一页”顺序阅读，或单击右上角的“FPACTool 帮助主页”随时返回本页。</p>\r\n\r\n<div class=\"tip\"><b>提示：</b>各主题页面均可在“相关主题”区域快速跳转到相邻主题。</div>\r\n\r\n</div>\r\n\r\n<!-- 上一下一页导航 -->\r\n<div class=\"navbar\">\r\n<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\"><tr>\r\n<td align=\"left\">&nbsp;</td>\r\n<td align=\"center\"><a href=\"index.htm\">主页</a></td>\r\n<td align=\"right\"><a href=\"Pack.htm\">下一页 &raquo;</a></td>\r\n</tr></table>\r\n</div>\r\n\r\n<!-- 页脚 -->\r\n<div class=\"footer\">\r\nFPACTool 帮助\r\n</div>\r\n\r\n</body>\r\n</html>\r\n";
        public static string pack_htm = "<!DOCTYPE HTML PUBLIC \"-//W3C//DTD HTML 4.01 Transitional//EN\" \"http://www.w3.org/TR/html4/loose.dtd\">\r\n<html lang=\"zh-CN\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\">\r\n<title>打包 PAC - FPACTool 帮助</title>\r\n<link rel=\"stylesheet\" href=\"style/style.css\">\r\n</head>\r\n<body>\r\n\r\n<!-- 顶部标题栏 -->\r\n<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" class=\"banner\">\r\n<tr>\r\n<td style=\"padding:10px 16px;\"><h1>打包 PAC</h1></td>\r\n<td style=\"padding:10px 16px; text-align:right;\"><a href=\"index.htm\" style=\"color:#FFFFFF;\">FPACTool 帮助主页</a></td>\r\n</tr>\r\n</table>\r\n\r\n<!-- 当前位置 -->\r\n<div class=\"crumb\"><b>位置：</b><a href=\"index.htm\">FPACTool 帮助</a> &gt; 使用 FPACTool &gt; 打包 PAC</div>\r\n\r\n<!-- 正文内容区 -->\r\n<div class=\"content\">\r\n\r\n<h2>功能简介</h2>\r\n<p>通过“打包”功能，可将硬盘上任意位置的文件与文件夹按照指定的目录结构整理为一个 PAC 文件，供游戏读取使用。</p>\r\n\r\n<h2>操作步骤</h2>\r\n<ol>\r\n<li>单击工具栏上的 <b>“新建”</b> 按钮，在弹出的对话框中指定 PAC 文件的保存位置与文件名。</li>\r\n<li>单击工具栏上的 <b>“添加”</b> 按钮下的<b>“添加文件”</b> 菜单项，选择一个或多个文件加入打包列表，也可以通过拖放的方式添加一个或多个文件。</li>\r\n<li>如需加入整个目录，请单击工具栏上的 <b>“添加”</b> 按钮下的<b>“添加文件夹”</b> 菜单项，选择要打包的文件夹，也可以通过拖放的方式来添加文件夹。</li>\r\n<li>添加完成后，列表会按目录树方式显示待打包内容，可双击文件夹查看内部文件。</li>\r\n<li>如果想移除某个文件或文件夹，可通过单击工具栏上的 <b>“删除”</b> 按钮来移除文件或文件夹。</li>\r\n<li>确认无误后单击 <b>“打包”</b> 按钮开始生成 PAC 文件。</li>\r\n</ol>\r\n\r\n<div class=\"note\">\r\n<b>注意：</b><li>打包过程中请勿关闭程序或修改正在打包的源文件，以免生成不完整的 PAC 文件。</li>\r\n<li>PAC 文件里不允许有空文件夹，所以当一个文件夹里没有文件的时候，会询问是否删除整个文件夹，否则无法删除文件夹。</li>\r\n</div>\r\n\r\n</div>\r\n\r\n<!-- 上一下一页导航 -->\r\n<div class=\"navbar\">\r\n<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\"><tr>\r\n<td align=\"left\"><a href=\"index.htm\">&laquo; 上一页</a></td>\r\n<td align=\"center\"><a href=\"index.htm\">主页</a></td>\r\n<td align=\"right\"><a href=\"Unpack.htm\">下一页 &raquo;</a></td>\r\n</tr></table>\r\n</div>\r\n\r\n<!-- 页脚 -->\r\n<div class=\"footer\">\r\nFPACTool 帮助\r\n</div>\r\n\r\n</body>\r\n</html>\r\n";
        public static string unpack_htm = "<!DOCTYPE HTML PUBLIC \"-//W3C//DTD HTML 4.01 Transitional//EN\" \"http://www.w3.org/TR/html4/loose.dtd\">\r\n<html lang=\"zh-CN\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\">\r\n<title>浏览/提取 PAC - FPACTool 帮助</title>\r\n<link rel=\"stylesheet\" href=\"style/style.css\">\r\n</head>\r\n<body>\r\n\r\n<!-- 顶部标题栏 -->\r\n<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" class=\"banner\">\r\n<tr>\r\n<td style=\"padding:10px 16px;\"><h1>浏览/提取 PAC</h1></td>\r\n<td style=\"padding:10px 16px; text-align:right;\"><a href=\"index.htm\" style=\"color:#FFFFFF;\">FPACTool 帮助主页</a></td>\r\n</tr>\r\n</table>\r\n\r\n<!-- 当前位置 -->\r\n<div class=\"crumb\"><b>位置：</b><a href=\"index.htm\">FPACTool 帮助</a> &gt; 使用 FPACTool &gt; 浏览/提取 PAC</div>\r\n\r\n<!-- 正文内容区 -->\r\n<div class=\"content\">\r\n\r\n<h2>功能简介</h2>\r\n<p>通过“浏览/提取”功能，可打开现有的 PAC 文件，浏览其中的目录与文件，并将需要的文件提取到硬盘上的指定文件夹。</p>\r\n\r\n<h2>操作步骤</h2>\r\n<ol>\r\n<li>单击工具栏上的 <b>“打开”</b> 按钮，选择要浏览/提取的 PAC 文件，也可以在未新建 PAC 文件的状态下通过拖放 PAC 文件的方式来打开 PAC 文件。</li>\r\n<li>打开后，PAC 内部的文件将以目录树方式显示在列表中。</li>\r\n<li>双击文件将自动将选中的文件提取到临时文件夹，并使用当前默认的打开方式进行预览，预览 DDS 格式图像文件将会自动唤起内置 DDS 浏览器来DDS 浏览。</li>\r\n<li>双击文件夹可进入子目录，双击“..”可返回上级目录。</li>\r\n<li>选中文件后，可直接通过单击工具栏上的</b>“提取选中”<b>按钮来执行单个文件提取，也可通过单击<b>“提取全部”</b>按钮来执行提取整个 PAC 文件可使用右键菜单或工具栏执行提取操作。</li>\r\n</ol>\r\n\r\n<p></p>\r\n\r\n<div class=\"tip\"><b>提示：</b>提取到的文件和文件夹将保存在指定的提前路径下的\"文件名_unpacked\"，以便核对提取结果。</div>\r\n\r\n</div>\r\n\r\n<!-- 上一下一页导航 -->\r\n<div class=\"navbar\">\r\n<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\"><tr>\r\n<td align=\"left\"><a href=\"Pack.htm\">&laquo; 上一页</a></td>\r\n<td align=\"center\"><a href=\"index.htm\">主页</a></td>\r\n<td align=\"right\"><a href=\"DDSView.htm\">下一页 &raquo;</a></td>\r\n</tr></table>\r\n</div>\r\n\r\n<!-- 页脚 -->\r\n<div class=\"footer\">\r\nFPACTool 帮助\r\n</div>\r\n\r\n</body>\r\n</html>\r\n";
        public static string ddsview_htm = "<!DOCTYPE HTML PUBLIC \"-//W3C//DTD HTML 4.01 Transitional//EN\" \"http://www.w3.org/TR/html4/loose.dtd\">\r\n<html lang=\"zh-CN\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\">\r\n<title>DDS 浏览 - FPACTool 帮助</title>\r\n<link rel=\"stylesheet\" href=\"style/style.css\">\r\n</head>\r\n<body>\r\n\r\n<!-- ========== 顶部标题栏 ========== -->\r\n<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" class=\"banner\">\r\n<tr>\r\n<td style=\"padding:10px 16px;\"><h1>DDS 浏览</h1></td>\r\n<td style=\"padding:10px 16px; text-align:right;\"><a href=\"index.htm\" style=\"color:#FFFFFF;\">FPACTool 帮助主页</a></td>\r\n</tr>\r\n</table>\r\n\r\n<!-- ========== 当前位置 ========== -->\r\n<div class=\"crumb\"><b>位置：</b><a href=\"index.htm\">FPACTool 帮助</a> &gt; 使用 FPACTool &gt; DDS 浏览</div>\r\n\r\n<!-- ========== 正文内容区 ========== -->\r\n<div class=\"content\">\r\n\r\n<!-- ↓↓↓ 在此开始编写页面正文 ↓↓↓ -->\r\n\r\n<h2>功能简介</h2>\r\n<p>当你打开一个 PAC 文件后，在浏览框内双击一个 DDS 文件将唤起本工具内置的 DDS 图像浏览器来预览选中的 DDS，从而省去要先提取再查看的麻烦，寻找需要的图片更便捷！</p>\r\n\r\n<h2>操作步骤</h2>\r\n<ol>\r\n<li>打开一个 PAC。</li>\r\n<li>找到 DDS 文件并双击，同时自动弹出 DDS 图像浏览窗口。</li>\r\n<li>单击 <b>“放大”</b> 或 <b>“缩小”</b> 按钮可缩放图片，也可通过按 Ctrl + 鼠标滚轮的方式缩放图片。</li>\r\n<li>单击 <b>“保存为...”</b> 按钮，可将当前 DDS 图像保存为 PNG、BMP、JPEG 或 TIFF 格式。</li>\r\n<li>单击 <b>“图像属性”</b> 按钮可查看当前 DDS 图像的尺寸、资源类型、纹理压缩等技术参数。</li>\r\n</ol>\r\n<!-- 注意框 -->\r\n<div class=\"note\"><b>注意：</b>本功能仅用于 DDS 图像的快速预览和导出，不支持将其他图像格式转换为 DDS。</div>\r\n</div>\r\n\r\n<!-- ========== 上一下一页导航 ========== -->\r\n<div class=\"navbar\">\r\n<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\"><tr>\r\n<td align=\"left\"><a href=\"Unpack.htm\">&laquo; 上一页</a></td>\r\n<td align=\"center\"><a href=\"index.htm\">主页</a></td>\r\n<td align=\"right\"><a href=\"FAQ.htm\">下一页 &raquo;</a></td>\r\n</tr></table>\r\n</div>\r\n\r\n<!-- ========== 页脚 ========== -->\r\n<div class=\"footer\">\r\nFPACTool 帮助\r\n</div>\r\n\r\n</body>\r\n</html>\r\n";
        public static string faq_htm = "<!DOCTYPE HTML PUBLIC \"-//W3C//DTD HTML 4.01 Transitional//EN\" \"http://www.w3.org/TR/html4/loose.dtd\">\r\n<html lang=\"zh-CN\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\">\r\n<title>疑难解答 - FPACTool 帮助</title>\r\n<link rel=\"stylesheet\" href=\"style/style.css\">\r\n</head>\r\n<body>\r\n\r\n<!-- 顶部标题栏 -->\r\n<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" class=\"banner\">\r\n<tr>\r\n<td style=\"padding:10px 16px;\"><h1>疑难解答</h1></td>\r\n<td style=\"padding:10px 16px; text-align:right;\"><a href=\"index.htm\" style=\"color:#FFFFFF;\">FPACTool 帮助主页</a></td>\r\n</tr>\r\n</table>\r\n\r\n<!-- 当前位置 -->\r\n<div class=\"crumb\"><b>位置：</b><a href=\"index.htm\">FPACTool 帮助</a> &gt; 使用 FPACTool &gt; 疑难解答</div>\r\n\r\n<!-- 正文内容区 -->\r\n<div class=\"content\">\r\n\r\n    <h2>常见问题</h2>\r\n\r\n    <h3>问：为什么程序无法打开某个 PAC 文件？</h3>\r\n    <p>答：它可能是非标准 FPAC 格式的文件或者它是较高版本的 FPAC 本工具尚未适配，需要后续版本支持。</p>\r\n\r\n    <h3>问：双击文件或文件夹为什么没有反应，有时还会卡顿？</h3>\r\n    <p>答：这个问题是多方面的：1)双击预览文件是依赖当前系统关联的默认程序，请自行配置文件类型打开方式。2)当前文件夹下文件数量过多，载入需要时间，等待期间就会卡顿，属正常现象，卡顿时长因电脑情况而异，如果程序长时间无响应，可尝试通过任务管理器结束进程后重新启动。3)有的 DDS 图像比较大，载入到内置浏览窗口也会卡顿，也属于正常现象。</p>\r\n\r\n    <h3>问：预览 DDS 出错，提示『文件既不是标准 DDS，也不是可识别的 LZ4 Frame DDS。』是怎么回事 ？</h3>\r\n    <p>答：该文件可能不是标准 DDS，或者采用了目前尚未适配的封装、压缩或像素格式。如果你确认它是游戏中正常使用的 DDS 文件，可以通过反馈渠道将问题文件发送给我，以便后续版本分析和适配。</p>\r\n\r\n    <h3>问：为什么打开已打包好的 PAC 文件只支持提取不支持增删文件？</h3>\r\n    <p>答：已打包的 PAC ，各文件在包内的偏移已经固定。添加或删除文件会导致后面的文件偏移发生改变，因此不能像普通文件夹一样直接修改。为避免生成损坏的 PAC，打开 PAC 后只允许浏览和提取。需要修改内容时，请重新添加需要打包的文件。</p>\r\n\r\n    <h3>问：DDS预览都支持了，为什么不支持DAT、TBL、JSON等格式的预览？</h3>\r\n    <p>答：DDS 是相对标准化的图像格式，虽然不同游戏可能采用不同的压缩或封装方式，但整体解析规则较为统一， 所以有提供通用的图片预览功能的必要。但是DAT、TBL、JSON 等文件通常保存游戏参数、文本、脚本或其他结构化数据，其内部格式往往因游戏、版本和用途而异，同一扩展名也不一定代表相同的数据结构。本工具以 PAC 文件的浏览、提取和重新打包为主要功能，不以游戏数据文件的解析和编辑为开发重点。如需查看或修改这些文件，请使用对应游戏或格式的专用工具。</p>\r\n\r\n    <h3>问：只支持三款游戏的 PAC 文件的打包和提取吗？</h3>\r\n    <p>答：不一定，如果是同引擎的且格式相同，就可以使用，尽管将来 PAC 有了迭代版，工具也会更新并适配。</p>\r\n\r\n    <h2>联系与反馈</h2>\r\n    <p>\r\n        如果你对本工具有什么意见和建议，欢迎反馈和补充！<br>\r\n        联系我需要登录吾爱破解论坛账号，然后给我发站内信。<br>\r\n        <span class=\"bold-red\">发送站内信的时候请遵守论坛版规，禁止留QQ、微信等联系方式，对利用私信留联系方式的行为将从重处罚！</span><br>\r\n        DDS图片格式已经行了全量适配，但依然可能存在未适配的DDS图片格式，如果你遇到了无法打开的DDS格式或遇到其他bug，也请与我联系。\r\n    </p>\r\n    <div class=\"tip\"><b><a href=\"https://www.52pojie.cn/home.php?mod=space&uid=368698\">点此反馈</a></b></div>\r\n\r\n</div>\r\n\r\n<!-- 上一下一页导航 -->\r\n<div class=\"navbar\">\r\n<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\"><tr>\r\n<td align=\"left\"><a href=\"DDSView.htm\">&laquo; 上一页</a></td>\r\n<td align=\"center\"><a href=\"index.htm\">主页</a></td>\r\n<td align=\"right\"><a href=\"Chagelog.htm\">下一页 &raquo;</a></td>\r\n</tr></table>\r\n</div>\r\n\r\n<!-- 页脚 -->\r\n<div class=\"footer\">\r\nFPACTool 帮助\r\n</div>\r\n\r\n</body>\r\n</html>\r\n";
        public static string changelog_htm = "<!DOCTYPE HTML PUBLIC \"-//W3C//DTD HTML 4.01 Transitional//EN\" \"http://www.w3.org/TR/html4/loose.dtd\">\r\n<html lang=\"zh-CN\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\">\r\n<title>更新日志 - FPACTool 帮助</title>\r\n<link rel=\"stylesheet\" href=\"style/style.css\">\r\n</head>\r\n<body>\r\n\r\n<!-- 顶部标题栏 -->\r\n<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" class=\"banner\">\r\n<tr>\r\n<td style=\"padding:10px 16px;\"><h1>更新日志</h1></td>\r\n<td style=\"padding:10px 16px; text-align:right;\"><a href=\"index.htm\" style=\"color:#FFFFFF;\">FPACTool 帮助主页</a></td>\r\n</tr>\r\n</table>\r\n\r\n<!-- 当前位置 -->\r\n<div class=\"crumb\"><b>位置：</b><a href=\"index.htm\">FPACTool 帮助</a> &gt; 更新日志</div>\r\n\r\n<!-- 正文内容区 -->\r\n<div class=\"content\">\r\n\r\n<h2>2026.10.04 —— V2.1</h2>\r\n<ol>\r\n\r\n<li><b>【细节优化】</b></li><br>\r\n1) 移除了打开 PAC 文件时又取消打开所弹出的未选择文件提示框，此为开发期间为调试程序所遗留，故做移除处理。<br>\r\n2) 生成 PAC 的时候，由先前的先检查后写入改为边检查边写入，提升处理效率。<br>\r\n3) 打包/提取完成后将询问是否打开输出目录，省去还要到文件浏览器一通乱翻的麻烦。\r\n<li><b>【文案调整】</b>调整了部分文案、修正错别字。</li>\r\n</ol>\r\n\r\n\r\n<h2>2026.09.18 —— V2.0</h2>\r\n<ol>\r\n<li><b>【全新界面】</b>工具界面全面更新！现在可以像使用压缩文件管理器一样浏览、打包和提取文件。</li>\r\n<li><b>【新增功能】</b>新增 DDS 图像浏览功能。打开 PAC 文件并找到 DDS 文件后，双击即可预览，同时支持保存为 JPG、PNG 等常规图片格式。</li>\r\n<li><b>【bug修复】</b>修复因打包生成的 PAC 文件路径哈希值错误而导致游戏闪退的问题。/li>\r\n</ol>\r\n\r\n<h2>2025.09.22 —— V1.0</h2>\r\n<ol>\r\n<li><b>【软件发布】</b>软件正式版发布。</li>\r\n</ol>\r\n\r\n</div>\r\n<br><br><br><br>\r\n<!-- 上一下一页导航 -->\r\n<div class=\"navbar\">\r\n<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\"><tr>\r\n<td align=\"left\"><a href=\"FAQ.htm\">&laquo; 上一页</a></td>\r\n<td align=\"center\"><a href=\"index.htm\">主页</a></td>\r\n<td align=\"right\"><a href=\"About.htm\">下一页 &raquo;</a></td>\r\n</tr></table>\r\n</div>\r\n\r\n<!-- 页脚 -->\r\n<div class=\"footer\">\r\nFPACTool 帮助\r\n</div>\r\n\r\n</body>\r\n</html>\r\n";
        public static string about_htm = "<!DOCTYPE HTML PUBLIC \"-//W3C//DTD HTML 4.01 Transitional//EN\" \"http://www.w3.org/TR/html4/loose.dtd\">\r\n<html lang=\"zh-CN\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\">\r\n<title>版本信息 - FPACTool 帮助</title>\r\n<link rel=\"stylesheet\" href=\"style/style.css\">\r\n</head>\r\n<body>\r\n\r\n<!-- 顶部标题栏 -->\r\n<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" class=\"banner\">\r\n<tr>\r\n<td style=\"padding:10px 16px;\"><h1>版本信息</h1></td>\r\n<td style=\"padding:10px 16px; text-align:right;\"><a href=\"index.htm\" style=\"color:#FFFFFF;\">FPACTool 帮助主页</a></td>\r\n</tr>\r\n</table>\r\n\r\n<!-- 当前位置 -->\r\n<div class=\"crumb\"><b>位置：</b><a href=\"index.htm\">FPACTool 帮助</a> &gt; 版本信息</div>\r\n\r\n<!-- 正文内容区 -->\r\n<div class=\"content\">\r\n\r\n<h2>应用信息</h2>\r\n<table class=\"tbl\" width=\"60%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">\r\n<tr><th width=\"30%\">项目</th><th>内容</th></tr>\r\n<tr><td>应用名称</td><td>FPAC Tool</td></tr>\r\n<tr><td>应用版本</td><td>Ver 2.1.0</td></tr>\r\n<tr><td>应用容量</td><td>1.0MB</td></tr>\r\n<tr><td>应用作者</td><td>52pojie@烟99</td></tr>\r\n</table>\r\n\r\n<h2>应用最低配置要求</h2>\r\n<ul>\r\n<li>操作系统：Microsoft Windows 7</li>\r\n<li>运行框架：Microsoft .NET Framework 4.5</li>\r\n<li>存储空间：512KB及以上的硬盘空闲空间</li>\r\n</ul>\r\n\r\n<div class=\"tip\"><b>提示：</b>查看程序内版本号，请选择主菜单中的&ldquo;关于&rdquo;或查看窗口标题栏。</div>\r\n\r\n<h2>致谢</h2>\r\n<p><a href=\"https://github.com/coinkillerl/FPACker/edit/master/README.md\" target=\"_blank\">coinkillerl</a> —— 参照了关于打包方法的文字描述。</p>\r\n\r\n<h2>郑重声明</h2>\r\n<p>1、本工具属于免费性质，由吾爱破解论坛会员制作，不收取任何费用！转载请注明出处，<span class=\"bold-red\">并“依样”打包转载</span>。</p>\r\n<p>2、本工具仅限用于游戏技术研究与学习交流。通过本工具提取的资源文件，<span class=\"bold-red\">其版权归游戏厂商及相关权利人所有，任何人不得将其用于商业用途或其他任何非法用途</span>；因违规使用而产生的一切后果，由使用者自行承担，<span class=\"bold-red\">工具作者不承担任何连带责任</span>。\r\n</p>\r\n<p>3、本工具的图标及美术作品版权归 52pojie@烟99 所有。任何个人或组织<span class=\"bold-red\">未经本人书面许可，不得擅自使用本工具图标</span>，否则本人将追究盗用者责任！</p>\r\n<p>4、本工具禁止以各种方式贩卖！如果您是通过付费途径获得的本工具，证明您已上当受骗，这样得到的文件安全性无法保证，转载者很可能向此软件植入广告推广、第三方联系方式，甚至还会有病毒木马。<span class=\"bold-red\">因使用付费得到的本软件造成的一切后果原作者概不承担。</span></p>\r\n\r\n</div>\r\n\r\n<!-- 上一下一页导航 -->\r\n<div class=\"navbar\">\r\n<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\"><tr>\r\n<td align=\"left\"><a href=\"Chagelog.htm\">&laquo; 上一页</a></td>\r\n<td align=\"center\"><a href=\"index.htm\">主页</a></td>\r\n<td align=\"right\">&nbsp;</td>\r\n</tr></table>\r\n</div>\r\n\r\n<!-- 页脚 -->\r\n<div class=\"footer\">\r\nFPACTool 帮助\r\n</div>\r\n\r\n</body>\r\n</html>\r\n";
